package com.jadhavr.erp.academic.entity;
import com.jadhavr.erp.academic.enums.SectionStatus; import com.jadhavr.erp.college.entity.College; import com.jadhavr.erp.common.entity.BaseAuditEntity; import com.jadhavr.erp.department.entity.Department; import com.jadhavr.erp.staff.entity.StaffProfile; import jakarta.persistence.*;
@Entity @Table(name="academic_sections",uniqueConstraints=@UniqueConstraint(columnNames={"academic_class_id","academic_year","code"}))
public class Section extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="college_id",nullable=false) private College college; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="department_id",nullable=false) private Department department; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="academic_class_id",nullable=false) private AcademicClass academicClass; @Column(name="academic_year",nullable=false,length=20) private String academicYear; @Column(nullable=false,length=150) private String name; @Column(nullable=false,length=30) private String code; @Column(nullable=false) private Integer capacity; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="class_teacher_id") private StaffProfile classTeacher; @Enumerated(EnumType.STRING) private SectionStatus status=SectionStatus.ACTIVE;
public Long getId(){return id;} public College getCollege(){return college;} public void setCollege(College v){college=v;} public Department getDepartment(){return department;} public void setDepartment(Department v){department=v;} public AcademicClass getAcademicClass(){return academicClass;} public void setAcademicClass(AcademicClass v){academicClass=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCode(){return code;} public void setCode(String v){code=v;} public Integer getCapacity(){return capacity;} public void setCapacity(Integer v){capacity=v;} public StaffProfile getClassTeacher(){return classTeacher;} public void setClassTeacher(StaffProfile v){classTeacher=v;} public SectionStatus getStatus(){return status;} public void setStatus(SectionStatus v){status=v;}}
